504.     ///
505.     #[verus_verify(external_body)]
506.     #[verus_spec(ret =>
507.         requires
508.             self.inv(),
509.             phys_addr.inv(),
510.         ensures
511.             self.inv(),
512.             ret <==> (
513.                 self@.allocated_frames.contains(phys_addr@)
514.                 || self@.free_frames.contains(phys_addr@)
515.             ),
516.     )]
517.     fn is_covered(&self, phys_addr: PageAligned<PhysicalAddress>) -> bool {
518.         let frame_number: usize = phys_addr.into_frame_number().into_raw_value();
519.         frame_number < self.bitmap.number_of_bits()
520.     }
